        uint8_t predictorIndex = *encoded++;
        int predictor = (predictorIndex >> 4) & 0x0F;
        int index = predictorIndex & 0x0F;

        while (*encoded != 0xFF) { // Assuming 0xFF marks end of packet
            int16_t sample1 = decodeSample(encoded, predictor, index, state);
            int16_t sample2 = decodeSample(encoded + 1, predictor, index, state);
            decoded[decodedBufferSize++] = sample1;
            decoded[decodedBufferSize++] = sample2;
            encoded += 2;
            totalSampleCount += 2;
        }

        encoded++; // Skip end of packet marker
    }

    int totalBytesWritten = decodedBufferSize * sizeof(int16_t);
    return totalBytesWritten;
}

