int decodeADPCMAudioBlock(const uint8_t* encoded, int16_t* decoded) {
    int channelCount = getTrackChannelCount();
    int sampleCount = 0;

    for (int channel = 0; channel < channelCount; ++channel) {
        ADPCMState state;
        initializeADPCMState(&state);
        uint8_t* channelData = const_cast<uint8_t*>(encoded + channel * getEncodedChannelSize());

        uint16_t predictorIndex = *(uint16_t*)(channelData);
        int index = predictorIndex & 0x0F;
        int predictor = (predictorIndex >> 4) & 0x0F;

        uint8_t* frameData = channelData + sizeof(uint16_t);
        int frameCount = getEncodedFrameCount(channelData);

        for (int frame = 0; frame < frameCount; ++frame) {
            int16_t sample1 = decodeSample(frameData[frame * 2], index, &state);
            int16_t sample2 = decodeSample(frameData[frame * 2 + 1], index, &state);

            decoded[sampleCount++] = sample1;
            decoded[sampleCount++] = sample2;
        }
    }

    return sampleCount * sizeof(int16_t);
